class Solution:
    def findMissingRanges(self, nums: list[int], lower: int, upper: int) -> list[list[int]]:
        res = []
        prev = lower - 1
        for num in nums + [upper + 1]:
            if num - prev >= 2:
                res.append([prev + 1, num - 1])
            prev = num
        return res

